(()=>{'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),mini=document.querySelector('#mini'),mx=mini.getContext('2d');
const N=24,types={worker:{name:'Worker',icon:'◈',cost:[50,20],hp:70,dmg:5,range:.8,speed:2.2,build:2},soldier:{name:'Soldier',icon:'⚔',cost:[70,20],hp:130,dmg:18,range:1,speed:1.75,build:3},archer:{name:'Archer',icon:'➶',cost:[55,40],hp:80,dmg:15,range:3.3,speed:1.55,build:3.5},siege:{name:'Siege',icon:'⬟',cost:[130,80],hp:190,dmg:38,range:4.5,speed:.85,build:6}};
const buildings={cc:{name:'Command Center',icon:'⌂',cost:[0,0],hp:1600,time:0,pop:30},gen:{name:'Generator',icon:'ϟ',cost:[100,0],hp:360,time:8,energy:22},mine:{name:'Crystal Mine',icon:'◆',cost:[80,30],hp:330,time:9,crystal:15},barracks:{name:'Barracks',icon:'▤',cost:[130,80],hp:520,time:12,pop:10},tower:{name:'Defense Tower',icon:'⌖',cost:[110,60],hp:450,time:10,range:5,dmg:22},lab:{name:'Research Lab',icon:'⌬',cost:[160,120],hp:420,time:15}};
let W=innerWidth,H=innerHeight,dpr=1,tw=48,th=25,zoom=1,camX=0,camY=0,last=0,elapsed=0,paused=true,over=false,difficulty='normal',wave=0,waveIn=90,energy=300,crystal=200,unitSeq=0,buildSeq=0,selected=[],buildMode=null,upgrade={dmg:0,hp:0,gather:0},sound=true,audio=null,frameN=0,fpsT=0;
const grid=[],units=[],structures=[],effects=[],projectiles=[],particles=[];let pointer=new Map(),gesture=null,hoverTile=null;
for(let y=0;y<N;y++){grid[y]=[];for(let x=0;x<N;x++){const d=Math.hypot((x-11.5)*.98,(y-11.5)*1.02),edge=d>11.4;const h=Math.max(0,Math.sin(x*.71+y*.31)*.44+Math.cos(y*.68-x*.22)*.35+Math.sin((x+y)*.28)*.25);grid[y][x]={x,y,h,edge,rock:edge||((Math.sin(x*13+y*7)*10000)%1>.984),node:((x===7&&y===9)||(x===16&&y===14)||(x===18&&y===7)||(x===5&&y===16))};}}
function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);mini.width=mini.clientWidth*dpr;mini.height=mini.clientHeight*dpr;mx.setTransform(dpr,0,0,dpr,0,0);tw=Math.max(34,Math.min(56,W/15));th=tw*.52;}
addEventListener('resize',resize);resize();
function iso(x,y,z=0){return {x:W/2+camX+(x-y)*tw*zoom/2,y:H*.47+camY+(x+y)*th*zoom/2-z*tw*zoom*.33}}
function tileAt(sx,sy){const a=(sx-W/2-camX)/(tw*zoom/2),b=(sy-H*.47-camY)/(th*zoom/2);return {x:Math.floor((a+b)/2),y:Math.floor((b-a)/2)}}
function key(x,y){return `${x},${y}`}function inMap(x,y){return x>=0&&y>=0&&x<N&&y<N}
function occupied(x,y){return structures.some(s=>s.hp>0&&s.x===x&&s.y===y)}function unitAt(x,y,side){return units.find(u=>u.hp>0&&u.side!==side&&Math.round(u.x)===x&&Math.round(u.y)===y)}
function entityAt(sx,sy){let hit=null,dist=Infinity;for(const e of [...structures,...units]){if(e.hp<=0)continue;const p=iso(e.x,e.y,e.z||0),r=(e.kind==='unit'?18:28)*zoom,d=Math.hypot(sx-p.x,sy-p.y);if(d<r&&d<dist){hit=e;dist=d}}return hit}
function makeUnit(type,side,x,y){const t=types[type];const u={id:++unitSeq,kind:'unit',type,side,x:x+.15,y:y+.15,hp:t.hp*(1+upgrade.hp*.15),maxHp:t.hp*(1+upgrade.hp*.15),dmg:t.dmg*(1+upgrade.dmg*.15),range:t.range,speed:t.speed,attackCd:Math.random()*.4,move:null,path:[],pathAt:0,target:null,buildProgress:0,gatherCd:0};units.push(u);if(side==='p')effect(x,y,'spawn');return u}
function makeBuilding(type,side,x,y,done=false){const t=buildings[type],s={id:++buildSeq,kind:'building',type,side,x,y,hp:done?t.hp:t.hp*.13,maxHp:t.hp,buildProgress:done?1:0,buildTime:t.time,attackCd:0,target:null};structures.push(s);if(done&&side==='p')effect(x,y,'build');return s}
function init(){units.length=structures.length=effects.length=projectiles.length=particles.length=0;energy=300;crystal=200;elapsed=0;wave=0;waveIn=90;unitSeq=buildSeq=0;upgrade={dmg:0,hp:0,gather:0};over=false;selected=[];buildMode=null;camX=0;camY=0;makeBuilding('cc','p',5,17,true);makeBuilding('cc','e',18,6,true);makeUnit('worker','p',6,18);makeUnit('worker','p',5,18);makeUnit('soldier','p',7,17);makeUnit('soldier','e',17,6);makeUnit('archer','e',18,7);makeBuilding('gen','p',4,17,true);makeBuilding('gen','e',19,6,true);makeBuilding('mine','p',7,16,true);makeBuilding('mine','e',17,7,true);makeBuilding('barracks','e',19,7,true);showToast('Colony systems online');renderActions();}
function owned(side){return units.filter(u=>u.side===side&&u.hp>0)}function popUsed(side){return owned(side).length}function popCap(side){return side==='p'?Math.max(30,structures.filter(s=>s.side===side&&s.type==='barracks'&&s.hp>0).length*10+20):30}
