function affordable(cost){return energy>=cost[0]&&crystal>=cost[1]}function spend(c){energy-=c[0];crystal-=c[1]}
function showToast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),1700)}
function beep(freq=520,d=.08){if(!sound)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function effect(x,y,type){effects.push({x,y,type,t:0,life:type==='boom'?1:.55});if(type==='build')beep(680,.13);if(type==='boom')beep(90,.28)}
function particlesAt(x,y,color,n=6){for(let i=0;i<n;i++)particles.push({x:x+(Math.random()-.5)*.4,y:y+(Math.random()-.5)*.4,vx:(Math.random()-.5)*1.5,vy:(Math.random()-.5)*1.5,life:.45+Math.random()*.5,color})}
function neighbors(n){return [[n.x+1,n.y],[n.x-1,n.y],[n.x,n.y+1],[n.x,n.y-1],[n.x+1,n.y+1],[n.x-1,n.y-1],[n.x+1,n.y-1],[n.x-1,n.y+1]]}
function findPath(s,tx,ty){tx=Math.max(0,Math.min(N-1,tx));ty=Math.max(0,Math.min(N-1,ty));const start={x:Math.round(s.x),y:Math.round(s.y)},goal={x:tx,y:ty};if(occupied(tx,ty)){const opts=neighbors(goal).filter(([x,y])=>inMap(x,y)&&!occupied(x,y));if(opts.length){[goal.x,goal.y]=opts[0]}}const open=[{...start,g:0,f:0}],came=new Map(),gscore=new Map([[key(start.x,start.y),0]]),closed=new Set();let steps=0;while(open.length&&steps++<800){open.sort((a,b)=>a.f-b.f);const c=open.shift(),ck=key(c.x,c.y);if(c.x===goal.x&&c.y===goal.y){let p=ck,path=[];while(came.has(p)){const [x,y]=p.split(',').map(Number);path.unshift({x:x+.15,y:y+.15});p=came.get(p)}return path}if(closed.has(ck))continue;closed.add(ck);for(const [x,y] of neighbors(c)){if(!inMap(x,y)||grid[y][x].edge||occupied(x,y)&&!(x===goal.x&&y===goal.y))continue;const nk=key(x,y),g=c.g+((x!==c.x&&y!==c.y)?1.414:1);if(g<=(gscore.get(nk)??Infinity)){came.set(nk,ck);gscore.set(nk,g);open.push({x,y,g,f:g+Math.hypot(goal.x-x,goal.y-y)})}}}return []}
function orderMove(u,x,y){u.move={x:x+.15,y:y+.15};u.path=findPath(u,x,y);u.pathAt=0;u.target=null}
function build(type,x,y,side='p'){const b=buildings[type];if(!inMap(x,y)||grid[y][x].edge||grid[y][x].rock||occupied(x,y))return false;if(type==='mine'&&!grid[y][x].node)return false;if(type!=='mine'&&grid[y][x].node)return false;if(side==='p'&&!affordable(b.cost))return false; if(side==='p'&&popUsed('p')>=popCap('p'))return false;if(side==='p')spend(b.cost);makeBuilding(type,side,x,y,false);effect(x,y,'dust');renderActions();return true}
function train(type,side='p'){const b=buildings.barracks,available=structures.some(s=>s.side===side&&s.type==='barracks'&&s.hp>0&&s.buildProgress>=1);if(!available){if(side==='p')showToast('Build a Barracks first');return false}const t=types[type];if(side==='p'&&!affordable(t.cost)){showToast('Not enough resources');return false}if(popUsed(side)>=popCap(side)){if(side==='p')showToast('Population limit reached');return false}if(side==='p')spend(t.cost);const barr=structures.find(s=>s.side===side&&s.type==='barracks'&&s.hp>0&&s.buildProgress>=1),u=makeUnit(type,side,barr.x+1,barr.y);u.hp=0;u.maxHp=t.hp;u.queueTime=t.build;u.queueTotal=t.build;u.side=side;u.spawnFrom=barr.id;u.kind='queue';if(side==='p'){beep(420,.12);showToast(`${t.name} in production`)}return true}

