function update(dt){if(paused||over)return;elapsed+=dt;waveIn-=dt;if(waveIn<=0){wave++;waveIn=90;enemyWave();showToast(`Enemy assault wave ${String(wave).padStart(2,'0')} incoming`);beep(170,.35)}
