for(let i=units.length-1;i>=0;i--){const u=units[i];if(u.hp<=0){if(u.kind==='queue'){if(u.queueTime<=0){const barr=structures.find(s=>s.id===u.spawnFrom&&s.hp>0);if(barr){u.kind='unit';u.hp=u.maxHp;u.x=barr.x+1;u.y=barr.y;u.move=null;u.path=[];effect(u.x,u.y,'spawn');if(u.side==='p')showToast(`${types[u.type].name} deployed`)}else units.splice(i,1)}else {u.queueTime-=dt;if(u.queueTime<=0){const barr=structures.find(s=>s.id===u.spawnFrom&&s.hp>0);if(barr){u.kind='unit';u.hp=u.maxHp;u.x=barr.x+1;u.y=barr.y;effect(u.x,u.y,'spawn')}else units.splice(i,1)}}}else units.splice(i,1);continue}if(u.kind!=='unit')continue;u.attackCd-=dt;
// basic automated combat target within acquisition range
let target=u.target&&u.target.hp>0?u.target:null;if(!target||distance(u,target)>Math.max(4,u.range+1.3)||target.side===u.side)target=nearestEnemy(u,Math.max(5,u.range+1.5));if(target){u.target=target;if(distance(u,target)<=u.range){u.move=null;u.path=[];if(u.attackCd<=0){if(u.type==='archer'||u.type==='siege')shoot(u,target,u.side==='p'?'#5be3cf':'#ff6875',u.dmg);else hit(target,u.dmg,u);u.attackCd=u.type==='siege'?1.7:.85}}else if(!u.move||distance(u,u.move)<.7){const tx=Math.round(target.x+(u.x<target.x?-Math.min(u.range*.55,2):Math.min(u.range*.55,2))),ty=Math.round(target.y+(u.y<target.y?-1:1));orderMove(u,tx,ty)}}
if(u.move&&u.pathAt<u.path.length){const p=u.path[u.pathAt],dx=p.x-u.x,dy=p.y-u.y,d=Math.hypot(dx,dy),step=u.speed*dt;if(d<step+.08){u.x=p.x;u.y=p.y;u.pathAt++;if(u.pathAt>=u.path.length)u.move=null}else{u.x+=dx/d*step;u.y+=dy/d*step}}else if(u.move){u.move=null}
}
// Enemy economy, scouting and periodic reinforcement
if(!window._aiTimer)window._aiTimer=0;window._aiTimer+=dt;if(window._aiTimer>12){window._aiTimer=0;enemyThink()}
for(const e of effects)e.t+=dt;for(let i=effects.length-1;i>=0;i--)if(effects[i].t>effects[i].life)effects.splice(i,1);for(const p of projectiles){p.t+=dt;p.x+=(p.tx-p.x)*Math.min(1,dt*8);p.y+=(p.ty-p.y)*Math.min(1,dt*8);if(p.t>p.life){if(p.target&&p.target.hp>0)hit(p.target,p.damage,p.source);particlesAt(p.tx,p.ty,p.color,3);p.dead=true}}for(let i=projectiles.length-1;i>=0;i--)if(projectiles[i].dead)projectiles.splice(i,1);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);
for(const s of structures)if(s.type==='cc'&&s.hp<=0){finish(s.side==='p'?'lose':'win');break}updateUI()}
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function nearestEnemy(a,r){let best=null,d=r;for(const e of [...units,...structures])if(e.side!==a.side&&e.hp>0&&e.kind!=='queue'){const q=distance(a,e);if(q<d){best=e;d=q}}return best}
function shoot(a,b,color,damage){const aa=iso(a.x,a.y,1),bb=iso(b.x,b.y,.5);projectiles.push({x:aa.x,y:aa.y,tx:bb.x,ty:bb.y,t:0,life:.2,target:b,source:a,damage,color});if(a.kind==='unit')beep(760,.035)}
function hit(target,damage,source){if(!target||target.hp<=0)return;let mult=1;if(source&&source.kind==='unit'){if(source.type==='soldier'&&target.type==='archer')mult=1.7;if(source.type==='archer'&&target.type==='siege')mult=1.7;if(source.type==='siege'&&target.kind==='building')mult=2.3;if(source.type==='siege'&&target.type==='soldier')mult=.75}target.hp-=damage*mult;particlesAt(target.x,target.y,target.side==='p'?'#50dcca':'#ff6476',4);if(target.hp<=0){effect(target.x,target.y,'boom');if(target.kind==='unit'&&target.side==='p'){}if(target.kind==='building'&&target.side==='p')showToast(`${buildings[target.type].name} destroyed`);if(target.kind==='building'&&target.side==='e'&&target.type==='cc')finish('win')}}
function enemyWave(){const es=structures.filter(s=>s.side==='e'&&s.type==='barracks'&&s.hp>0&&s.buildProgress===1);if(!es.length)return;let squad=['soldier','soldier','archer','siege'];if(difficulty==='easy')squad=['soldier','archer'];if(difficulty==='hard')squad=['soldier','soldier','archer','archer','siege'];for(let i=0;i<squad.length;i++){const u=makeUnit(squad[i],'e',es[0].x+1,es[0].y);u.target=structures.find(s=>s.side==='p'&&s.type==='cc');orderMove(u,5,17)}}
