if(!structures.some(s=>s.side==='e'&&s.type==='gen'&&s.hp>0&&s.buildProgress===1)){build('gen',20,5,'e')}if(crystal>80&&!structures.some(s=>s.side==='e'&&s.type==='lab'&&s.hp>0)){if(Math.random()<.18)build('lab',20,7,'e')}if(Math.random()<.23){const idle=enemyUnits.filter(u=>!u.move&&!u.target);if(idle.length){const army=owned('p').filter(u=>u.kind==='unit').length,near=enemyUnits.length;if(near>army*1.35){for(const u of idle)orderMove(u,18,6)}else{for(const u of idle)orderMove(u,5,17)}}}}
