function baseRound(x,y,r,fill,stroke){ctx.beginPath();ctx.ellipse(x,y,r*1.4,r*.65,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
