function enemyWave(){const es=structures.filter(s=>s.side==='e'&&s.type==='barracks'&&s.hp>0&&s.buildProgress===1);if(!es.length)return;let squad=['soldier','soldier','archer','siege'];if(difficulty==='easy')squad=['soldier','archer'];if(difficulty==='hard')squad=['soldier','soldier','archer','archer','siege'];for(const type of squad){const u=makeUnit(type,'e',es[0].x+1,es[0].y);u.target=structures.find(s=>s.side==='p'&&s.type==='cc');orderMove(u,5,17)}}
