function drawBuilding(s){const p=iso(s.x,s.y,grid[s.y]?.[s.x]?.h||0),player=s.side==='p',c=player?'#46c9b8':'#d94c60',dark=player?'#176b6b':'#702e43',w=tw*zoom*.72,h=th*zoom*.72,high=(s.type==='cc'?48:s.type==='tower'?35:s.type==='barracks'?29:23)*zoom;ctx.fillStyle='#18334265';ctx.beginPath();ctx.ellipse(p.x,p.y+th*zoom*.25,w*.8,h*.62,0,0,7);ctx.fill();ctx.fillStyle=dark;ctx.beginPath();ctx.moveTo(p.x-w/2,p.y);ctx.lineTo(p.x,p.y+h/2);ctx.lineTo(p.x,p.y+h/2+high);ctx.lineTo(p.x-w/2,p.y+high);ctx.closePath();ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(p.x+w/2,p.y);ctx.lineTo(p.x,p.y+h/2);ctx.lineTo(p.x,p.y+h/2+high);ctx.lineTo(p.x+w/2,p.y+high);ctx.closePath();ctx.fill();ctx.fillStyle=player?'#a2f5df':'#ff98a0';ctx.beginPath();ctx.moveTo(p.x,p.y-h/2);ctx.lineTo(p.x+w/2,p.y);ctx.lineTo(p.x,p.y+h/2);ctx.lineTo(p.x-w/2,p.y);ctx.closePath();ctx.fill();ctx.fillStyle='#f0f3df';ctx.font=`${Math.max(13,20*zoom)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(buildings[s.type].icon,p.x,p.y+high*.35);if(s.type==='cc'){ctx.strokeStyle=player?'#b8ffe7':'#ffc1b8';ctx.lineWidth=2*zoom;ctx.beginPath();ctx.arc(p.x,p.y-high*.15,8*zoom,0,Math.PI*2);ctx.stroke()}if(s.buildProgress<1){ctx.fillStyle='#091a26aa';ctx.fillRect(p.x-17*zoom,p.y-high-12*zoom,34*zoom,3*zoom);ctx.fillStyle='#72e4ce';ctx.fillRect(p.x-17*zoom,p.y-high-12*zoom,34*zoom*s.buildProgress,3*zoom)}if(s.hp<s.maxHp){ctx.fillStyle='#142531cc';ctx.fillRect(p.x-15*zoom,p.y-high-6*zoom,30*zoom,3*zoom);ctx.fillStyle=player?'#5de0c1':'#ff6a78';ctx.fillRect(p.x-15*zoom,p.y-high-6*zoom,30*zoom*Math.max(0,s.hp/s.maxHp),3*zoom)}if(selected.includes(s)){ctx.strokeStyle=player?'#9ffff0':'#ff9da7';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(p.x,p.y+4*zoom,w*.83,h*.7,0,0,7);ctx.stroke()}}
function drawUnit(u){const p=iso(u.x,u.y,grid[Math.max(0,Math.min(N-1,Math.floor(u.y)))][Math.max(0,Math.min(N-1,Math.floor(u.x)))].h),player=u.side==='p',c=player?'#55ddc5':'#f25d70',scale=zoom;ctx.fillStyle='#19374470';ctx.beginPath();ctx.ellipse(p.x,p.y+5*scale,9*scale,4*scale,0,0,7);ctx.fill();if(u.type==='siege'){ctx.fillStyle=player?'#266875':'#78384c';ctx.fillRect(p.x-10*scale,p.y-13*scale,20*scale,12*scale);ctx.fillStyle=c;ctx.fillRect(p.x-6*scale,p.y-18*scale,12*scale,7*scale)}else{ctx.fillStyle=player?'#197f79':'#9a334a';ctx.beginPath();ctx.moveTo(p.x,p.y-20*scale);ctx.lineTo(p.x+8*scale,p.y-7*scale);ctx.lineTo(p.x+6*scale,p.y+1*scale);ctx.lineTo(p.x-6*scale,p.y+1*scale);ctx.lineTo(p.x-8*scale,p.y-7*scale);ctx.closePath();ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.arc(p.x,p.y-17*scale,5*scale,0,7);ctx.fill();ctx.strokeStyle=player?'#b4fff0':'#ffc1be';ctx.lineWidth=2*scale;ctx.beginPath();ctx.moveTo(p.x+3*scale,p.y-9*scale);ctx.lineTo(p.x+10*scale,p.y-3*scale);ctx.stroke()}if(selected.includes(u)){baseRound(p.x,p.y+4*scale,9*scale,'#5be3cf20','#adfff1')}if(u.hp<u.maxHp){ctx.fillStyle='#132635';ctx.fillRect(p.x-9*scale,p.y-25*scale,18*scale,2.4*scale);ctx.fillStyle=player?'#62e2c7':'#ff6775';ctx.fillRect(p.x-9*scale,p.y-25*scale,18*scale*Math.max(0,u.hp/u.maxHp),2.4*scale)}}
function draw(){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#9bd5e7');sky.addColorStop(.58,'#c7e9e9');sky.addColorStop(1,'#e6e5d0');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);for(let y=0;y<N;y++)for(let x=0;x<N;x++){const p=iso(x,y);if(p.x< -80||p.x>W+80||p.y< -70||p.y>H+70)continue;drawTile(grid[y][x]);if(grid[y][x].rock&&!grid[y][x].edge&&(x*7+y*13)%31===1)drawTree(x,y)}
const ents=[...structures.filter(s=>s.hp>0),...units.filter(u=>u.hp>0&&u.kind==='unit')].sort((a,b)=>a.x+a.y-b.x-b.y);for(const e of ents)e.kind==='building'?drawBuilding(e):drawUnit(e);
if(buildMode&&hoverTile&&inMap(hoverTile.x,hoverTile.y)){const t=grid[hoverTile.y][hoverTile.x],p=iso(t.x,t.y,t.h),ok=canPlace(buildMode,t.x,t.y);ctx.fillStyle=ok?'#55e6c45c':'#ff59655e';ctx.strokeStyle=ok?'#9affdf':'#ff8b91';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+tw*zoom/2,p.y+th*zoom/2);ctx.lineTo(p.x,p.y+th*zoom);ctx.lineTo(p.x-tw*zoom/2,p.y+th*zoom/2);ctx.closePath();ctx.fill();ctx.stroke()}
for(const p of projectiles){ctx.strokeStyle=p.color;ctx.lineWidth=2;ctx.globalAlpha=.55;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+(p.tx-p.x)*.5,p.y+(p.ty-p.y)*.5);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#fff6d5';ctx.beginPath();ctx.arc(p.x,p.y,2.3,0,7);ctx.fill()}for(const p of particles){const q=iso(p.x,p.y,.3);ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(q.x,q.y,2.2*zoom,0,7);ctx.fill();ctx.globalAlpha=1}for(const e of effects){const p=iso(e.x,e.y,.2),f=e.t/e.life;ctx.globalAlpha=1-f;if(e.type==='boom'){ctx.fillStyle='#ffc66a';ctx.beginPath();ctx.arc(p.x,p.y,5+f*28,0,7);ctx.fill()}else if(e.type==='dust'){ctx.fillStyle='#e7e2bb';ctx.beginPath();ctx.arc(p.x,p.y,4+f*14,0,7);ctx.fill()}else{ctx.strokeStyle='#a7fff1';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,5+f*19,0,7);ctx.stroke()}ctx.globalAlpha=1}drawMini()}
function canPlace(type,x,y){if(!inMap(x,y)||grid[y][x].edge||grid[y][x].rock||occupied(x,y))return false;if(type==='mine'&&!grid[y][x].node)return false;if(type!=='mine'&&grid[y][x].node)return false;return affordable(buildings[type].cost)}

