function renderActions(){const box=document.querySelector('#actions');box.innerHTML='';const s=selected.length===1?selected[0]:null;let entries=[];if(s&&s.kind==='building'&&s.side==='p'&&s.type==='barracks'){document.querySelector('#dock-title').textContent='BARRACKS · TRAINING';entries=Object.entries(types).map(([k,t])=>({id:'train:'+k,name:t.name,icon:t.icon,cost:`${t.cost[0]}⚡ ${t.cost[1]}◆`,disabled:!affordable(t.cost)||popUsed('p')>=popCap('p')}))}else if(s&&s.kind==='building'&&s.side==='p'&&s.type==='lab'){document.querySelector('#dock-title').textContent='RESEARCH LAB · UPGRADES';entries=[['dmg','Weapon tuning','✦',120,80],['hp','Aegis plating','⬡',120,80],['gather','Flux efficiency','↯',90,110]].map(([k,n,i,e,c])=>({id:'upgrade:'+k,name:n,icon:i,cost:`${e}⚡ ${c}◆`,disabled:upgrade[k]>=3||!affordable([e,c]),level:upgrade[k]}))}else{document.querySelector('#dock-title').textContent=s&&s.kind==='unit'?'FIELD COMMAND':s?'COLONY COMMAND':'COLONY COMMAND';entries=actionDefs.map(([id,name,icon,cost])=>({id:'build:'+id,name,icon,cost,disabled:!affordable(buildings[id].cost)}));if(s&&s.kind==='unit')entries.unshift({id:'all',name:'Select Army',icon:'⚔',cost:'GROUP'})}if(selected.length>1){document.querySelector('#dock-title').textContent=`SQUAD CONTROL · ${selected.length} UNITS`;entries=[{id:'all',name:'Select Army',icon:'⚔',cost:'GROUP'},...actionDefs.map(([id,name,icon,cost])=>({id:'build:'+id,name,icon,cost,disabled:!affordable(buildings[id].cost)}))]}
