const base='http://127.0.0.1:9222';
const targets=await (await fetch(base+'/json')).json();
const page=targets.find(t=>t.type==='page');
const ws=new WebSocket(page.webSocketDebuggerUrl);
let id=0; const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
async function send(method,params={}){const i=++id;ws.send(JSON.stringify({id:i,method,params}));return await new Promise(r=>pending.set(i,r))}
async function ev(expression){const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result.result.value}
const cmd=async (x,y)=>send('Input.dispatchMouseEvent',{type:'mousePressed',x,y,button:'left',clickCount:1}).then(()=>send('Input.dispatchMouseEvent',{type:'mouseReleased',x,y,button:'left',clickCount:1}));
await send('Page.enable');await send('Runtime.enable'); await send('Page.navigate',{url:'http://127.0.0.1:8000'}); await new Promise(r=>setTimeout(r,500));
console.log('initial',await ev(`({title:document.title, viewport:[innerWidth,innerHeight],modal:document.querySelector('#modal-title').textContent,actions:[...document.querySelectorAll('#actions .action')].map(e=>e.innerText)})`));
await ev(`document.querySelector('#resumeBtn').click()`); await new Promise(r=>setTimeout(r,100));
// Compute valid tile candidates based on game map and current camera, prioritize close to colony.
const pos=await ev(`(()=>{const N=24,tw=Math.max(34,Math.min(56,innerWidth/15)),th=tw*.52,zoom=1,camX=0,camY=innerHeight*.03-(N-1)*th/2;const occ=new Set(['5,17','18,6','4,17','19,6','7,16','17,7','19,7']);let out=[];for(let y=0;y<N;y++)for(let x=0;x<N;x++){const d=Math.hypot((x-11.5)*.98,(y-11.5)*1.02),edge=d>11.4,h=Math.max(0,Math.sin(x*.71+y*.31)*.44+Math.cos(y*.68-x*.22)*.35+Math.sin((x+y)*.28)*.25),rock=edge||((Math.sin(x*13+y*7)*10000)%1>.984),node=(x===7&&y===16)||(x===17&&y===7)||(x===16&&y===14)||(x===5&&y===9);if(!edge&&!rock&&!node&&!occ.has(x+','+y)){const sx=innerWidth/2+((x-y)*tw/2),sy=innerHeight*.47+camY+(x+y)*th/2+h;out.push({x,y,sx,sy,d:Math.hypot(x-6,y-17)})}}return out.sort((a,b)=>a.d-b.d).slice(0,10)})()`);
console.log('placement candidates',pos);
await cmd(pos[0].sx,pos[0].sy);await new Promise(r=>setTimeout(r,100));
console.log('selection',await ev(`({name:document.querySelector('#sel-name').textContent, title:document.querySelector('#dock-title').textContent, actions:[...document.querySelectorAll('#actions .action')].map(e=>e.innerText)})`));
await ev(`document.querySelector('#actions .action').click()`); await new Promise(r=>setTimeout(r,100)); console.log('buildmode',await ev(`document.querySelector('#dock-note').textContent`));
await cmd(pos[0].sx,pos[0].sy); await new Promise(r=>setTimeout(r,100));console.log('after placement',await ev(`({toast:document.querySelector('#toast').textContent, selected:document.querySelector('#sel-name').textContent, energy:document.querySelector('#energy').textContent})`));
// select completed/under construction barracks via world canvas coordinate
await cmd(pos[0].sx,pos[0].sy-22);await new Promise(r=>setTimeout(r,200));console.log('barracks selection',await ev(`({name:document.querySelector('#sel-name').textContent,title:document.querySelector('#dock-title').textContent,actions:[...document.querySelectorAll('#actions .action')].map(e=>e.innerText)})`));
await ev(`document.querySelector('#pauseBtn').click()`);console.log('pause',await ev(`({title:document.querySelector('#modal-title').textContent,show:document.querySelector('#modal').classList.contains('show')})`));await ev(`document.querySelector('#resumeBtn').click()`);await ev(`document.querySelector('#pauseBtn').click()`);await ev(`document.querySelector('#restartBtn').click()`);console.log('restart',await ev(`({title:document.querySelector('#modal-title').textContent,energy:document.querySelector('#energy').textContent,modal:document.querySelector('#modal').classList.contains('show')})`));
ws.close();
EOF
