const enemy=await ev(`(()=>{const x=19,y=7,tw=Math.max(34,Math.min(56,innerWidth/15)),th=tw*.52,h=Math.max(0,Math.sin(x*.71+y*.31)*.44+Math.cos(y*.68-x*.22)*.35+Math.sin((x+y)*.28)*.25),camY=innerHeight*.03-23*th/2;return {x:innerWidth/2+(x-y)*tw/2,y:innerHeight*.47+camY+(x+y)*th/2-h*tw*.33}})()`);
