const ws=new WebSocket(target.webSocketDebuggerUrl);let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};await new Promise(r=>ws.onopen=r);
async function send(method,params={}){const n=++id;ws.send(JSON.stringify({id:n,method,params}));return await new Promise(resolve=>pending.set(n,resolve))}
async function evaluate(expression){const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result.result.value}
await send('Page.enable');await send('Runtime.enable');
for(const result of ['win','lose']){
 await send('Page.navigate',{url:'http://127.0.0.1:8000'});await new Promise(r=>setTimeout(r,350));
 const resultState=await evaluate(`(async()=>{let s=await (await fetch('/game.js')).text();s=s.replace('init();renderActions();updateUI();requestAnimationFrame(loop);','init();renderActions();updateUI();finish('${result}');');eval(s);return {title:document.querySelector('#modal-title').textContent,copy:document.querySelector('#modal-copy').textContent,restart:document.querySelector('#restartBtn').style.display,resume:document.querySelector('#resumeBtn').style.display,difficulty:document.querySelector('#difficulty').style.display,modal:document.querySelector('#modal').classList.contains('show')}})()`);
 console.log(result,JSON.stringify(resultState));
 const after=await evaluate(`(()=>{document.querySelector('#restartBtn').click();return {modal:document.querySelector('#modal').classList.contains('show'),energy:document.querySelector('#energy').textContent,crystal:document.querySelector('#crystal').textContent,restart:document.querySelector('#restartBtn').style.display,resume:document.querySelector('#resumeBtn').style.display,difficulty:document.querySelector('#difficulty').style.display}})()`);
 console.log(result+' restart',JSON.stringify(after));
}
ws.close();
EOF

